<script>(function(){var p=document.getElementById('preview'),box=document.getElementById('name-box'),x=document.getElementById('name_x'),y=document.getElementById('name_y'),w=document.getElementById('name_width'),fs=document.getElementById('font_size'),fc=document.getElementById('font_color'),drag=false,dx=0,dy=0;function scaleFont(){box.style.fontSize=(Number(fs.value)/842*p.clientWidth)+'px'}box.addEventListener('pointerdown',function(e){drag=true;box.setPointerCapture(e.pointerId);var r=box.getBoundingClientRect();dx=e.clientX-r.left;dy=e.clientY-r.top;box.classList.add('dragging')});box.addEventListener('pointermove',function(e){if(!drag)return;var pr=p.getBoundingClientRect(),left=Math.max(0,Math.min(pr.width-box.offsetWidth,e.clientX-pr.left-dx)),top=Math.max(0,Math.min(pr.height-box.offsetHeight,e.clientY-pr.top-dy));x.value=(left/pr.width*100).toFixed(3);y.value=(top/pr.height*100).toFixed(3);box.style.left=x.value+'%';box.style.top=y.value+'%'});box.addEventListener('pointerup',function(){drag=false;box.classList.remove('dragging')});w.addEventListener('input',function(){box.style.width=w.value+'%'});fs.addEventListener('input',scaleFont);window.addEventListener('resize',scaleFont);scaleFont();fc.addEventListener('input',function(){box.style.color=fc.value});document.querySelector('input[name=background]').addEventListener('change',function(){if(this.files[0])p.style.backgroundImage='url('+URL.createObjectURL(this.files[0])+')'});})();</script>
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script>document.querySelectorAll('.js-issue-batch-form').forEach(function(form){form.addEventListener('submit',function(event){event.preventDefault();Swal.fire({title:'ยืนยันการออกวุฒิบัตรทั้งรุ่น?',text:'ระบบจะออกวุฒิบัตรให้ผู้ผ่านเงื่อนไขใน "'+form.dataset.batchName+'"',icon:'question',showCancelButton:true,confirmButtonText:'ออกวุฒิบัตร',cancelButtonText:'ยกเลิก',confirmButtonColor:'#245d8f',reverseButtons:true}).then(function(result){if(result.isConfirmed)form.submit();});});});</script>
<script>document.querySelectorAll('.js-email-certificate-form').forEach(function(form){form.addEventListener('submit',function(event){event.preventDefault();Swal.fire({title:'ส่งวุฒิบัตรทางอีเมล?',text:'ระบบจะส่งไฟล์ PDF ไปที่ '+form.dataset.email,icon:'question',showCancelButton:true,confirmButtonText:'ส่งอีเมล',cancelButtonText:'ยกเลิก',confirmButtonColor:'#198754',reverseButtons:true}).then(function(result){if(result.isConfirmed)form.submit();});});});</script>
